/*
 * C++ (Eigen) side of the matrix "scenario" benchmarks (chain, fixed, cliff, batch,
 * block, tri, conv).  Counterpart of bench_scenarios_c.c: same sweeps (from
 * bench_scenarios.h), same data, same iteration counts, same row names.
 *
 * All input data is generated by the C library (matrix_fill_rand / matrix_fill_image /
 * matrix_make_lower_triangular) and converted, so both languages provably start from
 * bit-identical matrices.  Every timed call is followed by BENCH_CLOBBER(), mirroring
 * the BENCH_MEASURE macro in the C driver.
 */
#include "bench_scenarios_cpp.hpp"
#include "bench_scenarios.h"
#include "c_matrix/matrix.h"
#include "cpp_matrix/eigen_scenarios.hpp"
#include <Eigen/Dense>
#include <array>
#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <utility>

namespace {

using Eigen::Index;
using Eigen::MatrixXd;
using Eigen::VectorXd;

double now_ns() {
    return static_cast<double>(std::chrono::duration_cast<std::chrono::nanoseconds>(
                                   std::chrono::steady_clock::now().time_since_epoch())
                                   .count());
}

// Best-of-`repeats` per-iteration average (ns); warmup runs each repeat (see BENCH_MEASURE).
template <typename F>
double measure(F&& fn, int warmup, int iters, int repeats) {
    double best = -1.0;
    for (int r = 0; r < repeats; ++r) {
        for (int w = 0; w < warmup; ++w) {
            fn();
            BENCH_CLOBBER();
        }
        const double t0 = now_ns();
        for (int i = 0; i < iters; ++i) {
            fn();
            BENCH_CLOBBER();
        }
        const double t = (now_ns() - t0) / static_cast<double>(iters);
        if (best < 0.0 || t < best)
            best = t;
    }
    return best;
}

void emit(BenchReport& rp, const char* scenario, const char* variant, long param, std::size_t rows,
          std::size_t cols, int iters, double ns) {
    char name[96];
    bench_scn_name(name, sizeof(name), "cpp", scenario, variant, param, rows, cols);
    bench_report_row(&rp, name, rows, cols, iters, ns);
}

// Random matrix with the exact data of the C benchmark (LCG from the C library).
MatrixXd rand_matrix(std::size_t rows, std::size_t cols, unsigned int seed) {
    Matrix m = matrix_create(rows, cols);
    matrix_fill_rand(&m, seed);
    MatrixXd e = scn::from_c(m);
    matrix_destroy(&m);
    return e;
}

// ---- chain -----------------------------------------------------------------------------

template <std::size_t K, std::size_t Cap>
void run_chain_from(BenchReport& rp, const BenchOptions& o, std::size_t n,
                    const std::array<MatrixXd, Cap>& terms, MatrixXd& out) {
    if constexpr (K <= Cap) {
        const double work = bench_work_chain(static_cast<int>(K), static_cast<double>(n));
        const int iters = bench_iters_scaled(&o, work);
        const int warmup = bench_warmup_for(&o, work);
        const double t =
            measure([&] { scn::chain_sum<K>(out, terms); }, warmup, iters, o.repeats);
        emit(rp, "chain", "add", static_cast<long>(n), K, n, iters, t);
        run_chain_from<K + 1, Cap>(rp, o, n, terms, out);
    }
}

void run_chain(BenchReport& rp, const BenchOptions& o) {
    constexpr std::size_t cap = BENCH_CHAIN_MAX_K;
    for (int si = 0; si < BENCH_NUM_CHAIN_SIZES; ++si) {
        const std::size_t n = BENCH_CHAIN_SIZES[si];
        std::array<MatrixXd, cap> terms;
        for (std::size_t i = 0; i < cap; ++i) {
            terms[i] = rand_matrix(n, n, o.seed + static_cast<unsigned int>(i));
            BENCH_ESCAPE(terms[i].data());
        }
        MatrixXd out = MatrixXd::Zero(n, n);
        BENCH_ESCAPE(out.data());
        run_chain_from<BENCH_CHAIN_MIN_K, cap>(rp, o, n, terms, out);
        volatile double sink = out(0, 0);
        (void)sink;
    }
}

// ---- fixed -----------------------------------------------------------------------------

template <int N>
void run_fixed_n(BenchReport& rp, const BenchOptions& o) {
    using F = scn::Fixed<N>;
    using Mat = typename F::Mat;
    using Vec = typename F::Vec;

    // Same LCG data as fixedN_fill_rand() in the C driver, via the C library.
    auto load = [&](unsigned int seed) {
        Mat m;
        const MatrixXd r = rand_matrix(N, N, seed);
        for (int i = 0; i < N; ++i)
            for (int j = 0; j < N; ++j)
                m(i, j) = r(i, j);
        return m;
    };
    Mat a = load(o.seed), b = load(o.seed + 1u), c = load(o.seed + 2u);
    Mat out = Mat::Zero();
    Vec x, y = Vec::Zero();
    for (int i = 0; i < N; ++i)
        x(i) = i * 0.001;
    BENCH_ESCAPE(a.data()); BENCH_ESCAPE(b.data()); BENCH_ESCAPE(c.data());
    BENCH_ESCAPE(out.data()); BENCH_ESCAPE(x.data()); BENCH_ESCAPE(y.data());

    auto run = [&](const char* op, auto&& fn) {
        if (!bench_op_enabled(&o, op))
            return;
        const double work = bench_work_op(op, static_cast<double>(N));
        const int iters = bench_iters_scaled(&o, work);
        const int warmup = bench_warmup_for(&o, work);
        const double t = measure(fn, warmup, iters, o.repeats);
        emit(rp, "fixed", op, -1, N, N, iters, t);
    };
    run("transpose", [&] { F::transpose(a, out); });
    run("add", [&] { F::add(a, b, out); });
    run("sub", [&] { F::sub(a, b, out); });
    run("scale", [&] { F::scale(a, 2.5, out); });
    run("matvec", [&] { F::matvec(a, x, y); });
    run("mul", [&] { F::mul(a, b, out); });
    run("transpose_mul", [&] { F::transpose_mul(a, b, out); });
    run("add3", [&] { F::add3(a, b, c, out); });
    run("mul_add", [&] { F::mul_add(a, b, c, out); });

    volatile double sink = out(0, 0) + y(0);
    (void)sink;
}

template <int... Ns>
void run_fixed_all(BenchReport& rp, const BenchOptions& o, std::integer_sequence<int, Ns...>) {
    (run_fixed_n<BENCH_FIXED_MIN_N + Ns>(rp, o), ...);
}

void run_fixed(BenchReport& rp, const BenchOptions& o) {
    run_fixed_all(rp, o,
                  std::make_integer_sequence<int, BENCH_FIXED_MAX_N - BENCH_FIXED_MIN_N + 1>{});
}

// ---- cliff -----------------------------------------------------------------------------

void run_cliff(BenchReport& rp, const BenchOptions& o) {
    for (int si = 0; si < BENCH_NUM_CLIFF_SIZES; ++si) {
        const std::size_t n = BENCH_CLIFF_SIZES[si];
        MatrixXd a = rand_matrix(n, n, o.seed), b = rand_matrix(n, n, o.seed + 1u);
        MatrixXd out = MatrixXd::Zero(n, n);
        VectorXd x(static_cast<Index>(n)), y = VectorXd::Zero(static_cast<Index>(n));
        for (std::size_t i = 0; i < n; ++i)
            x(static_cast<Index>(i)) = static_cast<double>(i) * 0.001;
        BENCH_ESCAPE(a.data()); BENCH_ESCAPE(b.data()); BENCH_ESCAPE(out.data());
        BENCH_ESCAPE(x.data()); BENCH_ESCAPE(y.data());

        for (int oi = 0; oi < BENCH_NUM_CLIFF_OPS; ++oi) {
            const char* op = BENCH_CLIFF_OPS[oi];
            if (!bench_op_enabled(&o, op))
                continue;
            const double work = bench_work_op(op, static_cast<double>(n));
            const int iters = bench_iters_scaled(&o, work);
            const int warmup = bench_warmup_for(&o, work);
            double t = 0.0;
            if (std::strcmp(op, "add") == 0)
                t = measure([&] { out.noalias() = a + b; }, warmup, iters, o.repeats);
            else if (std::strcmp(op, "transpose") == 0)
                t = measure([&] { out.noalias() = a.transpose(); }, warmup, iters, o.repeats);
            else
                t = measure([&] { y.noalias() = a * x; }, warmup, iters, o.repeats);
            emit(rp, "cliff", op, -1, n, n, iters, t);
        }
        volatile double sink = out(0, 0) + y(0);
        (void)sink;
    }
}

// ---- batch -----------------------------------------------------------------------------

void run_batch(BenchReport& rp, const BenchOptions& o) {
    Matrix t4 = matrix_create(4, 4);
    matrix_fill_rand(&t4, o.seed);
    Eigen::Matrix4d t;
    for (int r = 0; r < 4; ++r)
        for (int c = 0; c < 4; ++c)
            t(r, c) = t4.data[r * 4 + c];
    matrix_destroy(&t4);
    BENCH_ESCAPE(t.data());

    for (int pi = 0; pi < BENCH_NUM_BATCH_POINTS; ++pi) {
        const std::size_t m = BENCH_BATCH_POINTS[pi];
        // Eigen works in place (via Map) on the C library's own buffers: no copy.
        Matrix pts = matrix_create(m, 4), out = matrix_create(m, 4);
        matrix_fill_rand(&pts, o.seed + 1u);
        BENCH_ESCAPE(pts.data); BENCH_ESCAPE(out.data);

        const double work = bench_work_batch(static_cast<double>(m));
        const int iters = bench_iters_scaled(&o, work);
        const int warmup = bench_warmup_for(&o, work);
        const double tm = measure(
            [&] { scn::transform_points4(t, pts.data, out.data, static_cast<Index>(m)); }, warmup,
            iters, o.repeats);
        emit(rp, "batch", "xform4", -1, m, 4, iters, tm);

        volatile double sink = out.data[0];
        (void)sink;
        matrix_destroy(&pts);
        matrix_destroy(&out);
    }
}

// ---- block -----------------------------------------------------------------------------

void run_block(BenchReport& rp, const BenchOptions& o) {
    const std::size_t n = BENCH_BLOCK_N;
    MatrixXd a = rand_matrix(n, n, o.seed), b = rand_matrix(n, n, o.seed + 1u);
    MatrixXd d = MatrixXd::Zero(n, n);
    BENCH_ESCAPE(a.data()); BENCH_ESCAPE(b.data()); BENCH_ESCAPE(d.data());

    for (int bi = 0; bi < BENCH_NUM_BLOCK_SIZES; ++bi) {
        const Index bs = static_cast<Index>(BENCH_BLOCK_SIZES[bi]);
        for (int vi = 0; vi < 2; ++vi) {
            const char* variant = vi == 0 ? "copy" : "mul";
            const double work = bench_work_block(variant, static_cast<double>(bs));
            const int iters = bench_iters_scaled(&o, work);
            const int warmup = bench_warmup_for(&o, work);
            double t;
            if (vi == 0)
                t = measure(
                    [&] {
                        scn::block_copy(a, BENCH_BLOCK_A_ROW, BENCH_BLOCK_A_COL, d,
                                        BENCH_BLOCK_O_ROW, BENCH_BLOCK_O_COL, bs);
                    },
                    warmup, iters, o.repeats);
            else
                t = measure(
                    [&] {
                        scn::block_mul(a, BENCH_BLOCK_A_ROW, BENCH_BLOCK_A_COL, b,
                                       BENCH_BLOCK_B_ROW, BENCH_BLOCK_B_COL, d, BENCH_BLOCK_O_ROW,
                                       BENCH_BLOCK_O_COL, bs);
                    },
                    warmup, iters, o.repeats);
            emit(rp, "block", variant, BENCH_BLOCK_N, static_cast<std::size_t>(bs),
                 static_cast<std::size_t>(bs), iters, t);
        }
    }
    volatile double sink = d(0, 0);
    (void)sink;
}

// ---- tri -------------------------------------------------------------------------------

void run_tri(BenchReport& rp, const BenchOptions& o) {
    for (int si = 0; si < BENCH_NUM_TRI_SIZES; ++si) {
        const std::size_t n = BENCH_TRI_SIZES[si];
        Matrix ac = matrix_create(n, n), lc = matrix_create(n, n);
        matrix_fill_rand(&ac, o.seed);
        matrix_make_lower_triangular(&ac, &lc);
        const MatrixXd a = scn::from_c(ac), l = scn::from_c(lc);
        matrix_destroy(&ac);
        matrix_destroy(&lc);
        const MatrixXd rhs = rand_matrix(n, n, o.seed + 1u);
        MatrixXd x = MatrixXd::Zero(n, n), s = MatrixXd::Zero(n, n);
        BENCH_ESCAPE(a.data()); BENCH_ESCAPE(rhs.data()); BENCH_ESCAPE(l.data());
        BENCH_ESCAPE(x.data()); BENCH_ESCAPE(s.data());

        const double work = bench_work_tri(static_cast<double>(n));
        const int iters = bench_iters_scaled(&o, work);
        const int warmup = bench_warmup_for(&o, work);

        double t = measure([&] { scn::trsm_lower(l, rhs, x); }, warmup, iters, o.repeats);
        emit(rp, "tri", "trsm", -1, n, n, iters, t);
        t = measure([&] { scn::syrk_lower(a, s); }, warmup, iters, o.repeats);
        emit(rp, "tri", "syrk", -1, n, n, iters, t);

        volatile double sink = x(0, 0) + s(0, 0);
        (void)sink;
    }
}

// ---- conv ------------------------------------------------------------------------------

void write_conv_images(const BenchOptions& o, const Matrix& in, const MatrixXd& out) {
    Matrix oc = matrix_create(static_cast<std::size_t>(out.rows()),
                              static_cast<std::size_t>(out.cols()));
    scn::to_c(out, oc);
    const std::string dir = o.image_dir;
    const std::string pin = dir + "/conv_input_cpp.pgm", pout = dir + "/conv_output_cpp.pgm";
    if (matrix_write_pgm(&in, pin.c_str()) != 0)
        std::fprintf(stderr, "warning: could not write %s\n", pin.c_str());
    if (matrix_write_pgm(&oc, pout.c_str()) != 0)
        std::fprintf(stderr, "warning: could not write %s\n", pout.c_str());
    matrix_destroy(&oc);
}

void run_conv(BenchReport& rp, const BenchOptions& o) {
    const double kernel[9] = BENCH_CONV_KERNEL_INIT;
    for (int si = 0; si < BENCH_NUM_CONV_SIZES; ++si) {
        const std::size_t n = BENCH_CONV_SIZES[si];
        Matrix ic = matrix_create(n, n);
        matrix_fill_image(&ic, o.seed);
        const MatrixXd img = scn::from_c(ic);
        MatrixXd out = MatrixXd::Zero(n - 2, n - 2);
        BENCH_ESCAPE(img.data()); BENCH_ESCAPE(out.data()); BENCH_ESCAPE(kernel);

        const double work = bench_work_conv(static_cast<double>(n));
        const int iters = bench_iters_scaled(&o, work);
        const int warmup = bench_warmup_for(&o, work);
        const double t =
            measure([&] { scn::conv3x3(img, kernel, out); }, warmup, iters, o.repeats);
        emit(rp, "conv", "blur3x3", -1, n, n, iters, t);

        if (n == BENCH_CONV_IMAGE_N && o.image_dir[0])
            write_conv_images(o, ic, out); // after timing: no I/O in the timed region
        volatile double sink = out(0, 0);
        (void)sink;
        matrix_destroy(&ic);
    }
}

} // namespace

void bench_run_scenarios_cpp(BenchReport& rp, const BenchOptions& o) {
    if (bench_scenario_enabled(&o, BENCH_SCN_CHAIN)) {
        bench_report_section(&rp, "Scenario: expression chain  A1 + ... + Ak  (k = 2..16, N = 32..512)");
        run_chain(rp, o);
    }
    if (bench_scenario_enabled(&o, BENCH_SCN_FIXED)) {
        bench_report_section(&rp, "Scenario: compile-time-sized matrices  (N = 2..16)");
        run_fixed(rp, o);
    }
    if (bench_scenario_enabled(&o, BENCH_SCN_CLIFF)) {
        bench_report_section(&rp, "Scenario: cache-cliff size sweep  (N = 16..2048)");
        run_cliff(rp, o);
    }
    if (bench_scenario_enabled(&o, BENCH_SCN_BATCH)) {
        bench_report_section(&rp, "Scenario: 4x4 transform over M points");
        run_batch(rp, o);
    }
    if (bench_scenario_enabled(&o, BENCH_SCN_BLOCK)) {
        bench_report_section(&rp, "Scenario: submatrix block copy / multiply");
        run_block(rp, o);
    }
    if (bench_scenario_enabled(&o, BENCH_SCN_TRI)) {
        bench_report_section(&rp, "Scenario: triangular solve + symmetric rank-k update");
        run_tri(rp, o);
    }
    if (bench_scenario_enabled(&o, BENCH_SCN_CONV)) {
        bench_report_section(&rp, "Scenario: 3x3 convolution (blur)");
        run_conv(rp, o);
    }
}
